  "implementation": "import heapq

def solve(case):
    payload = case.get('payload')
    if not payload:
        raise ValueError('Missing payload')
    nodes = payload.get('nodes')
    threshold = payload.get('utility_threshold')
    if not isinstance(nodes, list) or threshold is None:
        raise ValueError('Invalid case structure')
    node_map = {}
    children = {}
    for n in nodes:
        nid = n.get('id')
        parent = n.get('parent')
        depth = n.get('depth')
        removable = n.get('removable')
        utility = n.get('utility')
        if nid is None or parent is None or depth is None or removable is None or utility is None:
            raise ValueError('Missing required field in node')
        if not isinstance(nid, str) or not isinstance(parent, (str, type(None))):
            raise ValueError('Invalid id or parent')
        node_map[nid] = n
        children.setdefault(nid, set())
        if parent is not None:
            children.setdefault(parent, set()).add(nid)
    removed = set()
    heap = []
    in_queue = set()
    for nid, n in node_map.items():
        item = (-n['depth'], nid)
        heapq.heappush(heap, item)
        in_queue.add(nid)
    visit_order = []
    while heap:
        neg_depth, nid = heapq.heappop(heap)
        in_queue.discard(nid)
        if nid in removed:
            continue
        visit_order.append(nid)
        node = node_map[nid]
        if len(children.get(nid, set())) == 0 and node['removable'] and node['utility'] <= threshold:
            removed.add(nid)
            parent = node.get('parent')
            if parent is not None and parent not in removed:
                children[parent].discard(nid)
                if parent not in in_queue:
                    pnode = node_map[parent]
                    heapq.heappush(heap, (-pnode['depth'], parent))
                    in_queue.add(parent)
    retained_ids = [nid for nid in sorted(node_map.keys(), key=lambda x: (node_map[x]['depth'], x)) if nid not in removed]
    return {'retained_ids': retained_ids, 'visit_order': visit_order}
